import{_ as i,a0 as l,w as d,s as o,I as s,x as n,a1 as p,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"開發一個 Linux 調試器（二）：斷點 | LCTT x X-CMD","titleTemplate":false,"description":"開發一個 Linux 調試器（二）：斷點 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開發一個 Linux 調試器（二）：斷點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開發一個 Linux 調試器（二）：斷點 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170324 Writing a Linux Debugger Part 2 Breakpoints","title":"開發一個 Linux 調試器（二）：斷點","tag":"201706","desc":""},"relativePath":"201706/20170324 Writing a Linux Debugger Part 2 Breakpoints.md","filePath":"[post].md"}'),c={name:"201706/20170324 Writing a Linux Debugger Part 2 Breakpoints.md"};function b(u,a,g,h,m,k){const e=l("Link");return d(),o("div",null,[a[25]||(a[25]=s("h1",{id:"開發一個-linux-調試器-二-斷點",tabindex:"-1"},[n("開發一個 Linux 調試器（二）：斷點 "),s("a",{class:"header-anchor",href:"#開發一個-linux-調試器-二-斷點","aria-label":"Permalink to “開發一個 Linux 調試器（二）：斷點”"},"​")],-1)),a[26]||(a[26]=s("p",null,"在該系列的第一部分，我們寫了一個小的進程啓動器，作為我們調試器的基礎。在這篇Blog中，我們會學習在 x86 Linux 上斷點是如何工作的，以及如何給我們工具添加設置斷點的能力。",-1)),a[27]||(a[27]=s("h3",{id:"系列文章索引",tabindex:"-1"},[n("系列文章索引 "),s("a",{class:"header-anchor",href:"#系列文章索引","aria-label":"Permalink to “系列文章索引”"},"​")],-1)),a[28]||(a[28]=s("p",null,"隨着後面文章的發佈，這些鏈接會逐漸生效。",-1)),s("ol",null,[s("li",null,[p(e,{href:"https://linux.cn/article-8626-1.html"},{default:t(()=>[...a[0]||(a[0]=[n("準備環境",-1)])]),_:1})]),s("li",null,[p(e,{href:"https://github.com/TartanLlama/minidbg/tree/tut_break"},{default:t(()=>[...a[1]||(a[1]=[n("斷點",-1)])]),_:1})]),a[2]||(a[2]=s("li",null,"寄存器和內存",-1)),a[3]||(a[3]=s("li",null,"Elves 和 dwarves",-1)),a[4]||(a[4]=s("li",null,"源碼和信號",-1)),a[5]||(a[5]=s("li",null,"源碼層逐步執行",-1)),a[6]||(a[6]=s("li",null,"源碼層斷點",-1)),a[7]||(a[7]=s("li",null,"調用棧",-1)),a[8]||(a[8]=s("li",null,"讀取變量 10.之後步驟",-1))]),a[29]||(a[29]=r(`<h3 id="斷點是如何形成的" tabindex="-1">斷點是如何形成的？ <a class="header-anchor" href="#斷點是如何形成的" aria-label="Permalink to “斷點是如何形成的？”">​</a></h3><p>有兩種類型的斷點：硬件和軟件。硬件斷點通常涉及到設置與體系結構相關的寄存器來為你產生斷點，而軟件斷點則涉及到修改正在執行的代碼。在這篇文章中我們只會關注軟件斷點，因為它們比較簡單，而且可以設置任意多斷點。在 x86 機器上任一時刻你最多隻能有 4 個硬件斷點，但是它們能讓你在讀取或者寫入給定地址時觸發，而不是隻有當代碼執行到那裏的時候。</p><p>我前面説軟件斷點是通過修改正在執行的代碼實現的，那麼問題就來了：</p><ul><li>我們如何修改代碼？</li><li>為了設置斷點我們要做什麼修改？</li><li>如何告知調試器？</li></ul><p>第一個問題的答案顯然是 <code>ptrace</code>。我們之前已經用它為我們的程序設置跟蹤並繼續程序的執行，但我們也可以用它來讀或者寫內存。</p><p>當執行到斷點時，我們的更改要讓處理器暫停並給程序發送信號。在 x86 機器上這是通過 <code>int 3</code> 重寫該地址上的指令實現的。x86 機器有個中斷向量表（interrupt vector table），操作系統能用它來為多種事件註冊處理程序，例如頁故障、保護故障和無效操作碼。它就像是註冊錯誤處理回調函數，但是是在硬件層面的。當處理器執行 <code>int 3</code> 指令時，控制權就被傳遞給斷點中斷處理器，對於 Linux 來説，就是給進程發送 <code>SIGTRAP</code> 信號。你可以在下圖中看到這個進程，我們用 <code>0xcc</code> 覆蓋了 <code>mov</code> 指令的第一個字節，它是 <code>init 3</code> 的指令代碼。</p><p><img src="http://blog.tartanllama.xyz/assets/breakpoint.png" alt="斷點"></p><p>謎題的最後一個部分是調試器如何被告知中斷的。如果你回顧前面的文章，我們可以用 <code>waitpid</code> 來監聽被髮送給被調試的程序的信號。這裏我們也可以這樣做：設置斷點、繼續執行程序、調用 <code>waitpid</code> 並等待直到發生 <code>SIGTRAP</code>。然後就可以通過打印已運行到的源碼位置、或改變有圖形用户界面的調試器中關注的代碼行，將這個斷點傳達給用户。</p><h3 id="實現軟件斷點" tabindex="-1">實現軟件斷點 <a class="header-anchor" href="#實現軟件斷點" aria-label="Permalink to “實現軟件斷點”">​</a></h3><p>我們會實現一個 <code>breakpoint</code> 類來表示某個位置的斷點，我們可以根據需要啓用或者停用該斷點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class breakpoint {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    breakpoint(pid_t pid, std::intptr_t addr)</span></span>
<span class="line"><span>        : m_pid{pid}, m_addr{addr}, m_enabled{false}, m_saved_data{}</span></span>
<span class="line"><span>    {}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    void enable();</span></span>
<span class="line"><span>    void disable();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    auto is_enabled() const -&gt; bool { return m_enabled; }</span></span>
<span class="line"><span>    auto get_address() const -&gt; std::intptr_t { return m_addr; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    pid_t m_pid;</span></span>
<span class="line"><span>    std::intptr_t m_addr;</span></span>
<span class="line"><span>    bool m_enabled;</span></span>
<span class="line"><span>    uint64_t m_saved_data; //data which used to be at the breakpoint address</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>這裏的大部分代碼都是跟蹤狀態；真正神奇的地方是 <code>enable</code> 和 <code>disable</code> 函數。</p><p>正如我們上面學到的，我們要用 <code>int 3</code> 指令 - 編碼為 <code>0xcc</code> - 替換當前指定地址的指令。我們還要保存該地址之前的值，以便後面恢復該代碼；我們不想忘了執行用户（原來）的代碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void breakpoint::enable() {</span></span>
<span class="line"><span>    m_saved_data = ptrace(PTRACE_PEEKDATA, m_pid, m_addr, nullptr);</span></span>
<span class="line"><span>    uint64_t int3 = 0xcc;</span></span>
<span class="line"><span>    uint64_t data_with_int3 = ((m_saved_data &amp; ~0xff) | int3); //set bottom byte to 0xcc</span></span>
<span class="line"><span>    ptrace(PTRACE_POKEDATA, m_pid, m_addr, data_with_int3);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    m_enabled = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>PTRACE_PEEKDATA</code> 請求告知 <code>ptrace</code> 如何讀取被跟蹤進程的內存。我們給它一個進程 ID 和一個地址，然後它返回給我們該地址當前的 64 位內容。 <code>(m_saved_data &amp; ~0xff)</code> 把這個數據的低位字節置零，然後我們用它和我們的 <code>int 3</code> 指令按位或（<code>OR</code>）來設置斷點。最後我們通過 <code>PTRACE_POKEDATA</code> 用我們的新數據覆蓋那部分內存來設置斷點。</p><p><code>disable</code> 的實現比較簡單，我們只需要恢復用 <code>0xcc</code> 所覆蓋的原始數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void breakpoint::disable() {</span></span>
<span class="line"><span>    ptrace(PTRACE_POKEDATA, m_pid, m_addr, m_saved_data);</span></span>
<span class="line"><span>    m_enabled = false;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="在調試器中增加斷點" tabindex="-1">在調試器中增加斷點 <a class="header-anchor" href="#在調試器中增加斷點" aria-label="Permalink to “在調試器中增加斷點”">​</a></h3><p>為了支持通過用户界面設置斷點，我們要在 debugger 類修改三個地方：</p><ol><li>給 <code>debugger</code> 添加斷點存儲數據結構</li><li>添加 <code>set_breakpoint_at_address</code> 函數</li><li>給我們的 <code>handle_command</code> 函數添加 <code>break</code> 命令</li></ol><p>我會將我的斷點保存到 <code>std::unordered_map&lt;std::intptr_t, breakpoint&gt;</code> 結構，以便能簡單快速地判斷一個給定的地址是否有斷點，如果有的話，取回該 breakpoint 對象。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class debugger {</span></span>
<span class="line"><span>    //...</span></span>
<span class="line"><span>    void set_breakpoint_at_address(std::intptr_t addr);</span></span>
<span class="line"><span>    //...</span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    //...</span></span>
<span class="line"><span>    std::unordered_map&lt;std::intptr_t,breakpoint&gt; m_breakpoints;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在 <code>set_breakpoint_at_address</code> 函數中我們會新建一個 breakpoint 對象，啓用它，把它添加到數據結構裏，並給用户打印一條信息。如果你喜歡的話，你可以重構所有的輸出信息，從而你可以將調試器作為庫或者命令列工具使用，為了簡便，我把它們都整合到了一起。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void debugger::set_breakpoint_at_address(std::intptr_t addr) {</span></span>
<span class="line"><span>    std::cout &lt;&lt; &quot;Set breakpoint at address 0x&quot; &lt;&lt; std::hex &lt;&lt; addr &lt;&lt; std::endl;</span></span>
<span class="line"><span>    breakpoint bp {m_pid, addr};</span></span>
<span class="line"><span>    bp.enable();</span></span>
<span class="line"><span>    m_breakpoints[addr] = bp;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在我們會在我們的命令處理程序中增加對我們新函數的調用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>void debugger::handle_command(const std::string&amp; line) {</span></span>
<span class="line"><span>    auto args = split(line,&#39; &#39;);</span></span>
<span class="line"><span>    auto command = args[0];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (is_prefix(command, &quot;cont&quot;)) {</span></span>
<span class="line"><span>        continue_execution();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    else if(is_prefix(command, &quot;break&quot;)) {</span></span>
<span class="line"><span>        std::string addr {args[1], 2}; //naively assume that the user has written 0xADDRESS</span></span>
<span class="line"><span>        set_breakpoint_at_address(std::stol(addr, 0, 16));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    else {</span></span>
<span class="line"><span>        std::cerr &lt;&lt; &quot;Unknown command\\n&quot;;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我刪除了字符串中的前兩個字符並對結果調用 <code>std::stol</code>，你也可以讓該解析更健壯一些。<code>std::stol</code> 可以將字符串按照所給基數轉化為整數。</p><h3 id="從斷點繼續執行" tabindex="-1">從斷點繼續執行 <a class="header-anchor" href="#從斷點繼續執行" aria-label="Permalink to “從斷點繼續執行”">​</a></h3><p>如果你嘗試這樣做，你可能會發現，如果你從斷點處繼續執行，不會發生任何事情。這是因為斷點仍然在內存中，因此一直被重複命中。簡單的解決辦法就是停用這個斷點、運行到下一步、再次啓用這個斷點、然後繼續執行。不過我們還需要更改程序計數器，指回到斷點前面，這部分內容會留到下一篇關於操作寄存器的文章中介紹。</p><h3 id="測試它" tabindex="-1">測試它 <a class="header-anchor" href="#測試它" aria-label="Permalink to “測試它”">​</a></h3><p>當然，如果你不知道要在哪個地址設置，那麼在某些地址設置斷點並非很有用。後面我們會學習如何在函數名或者代碼行設置斷點，但現在我們可以通過手動實現。</p><p>測試你調試器的簡單方法是寫一個 hello world 程序，這個程序輸出到 <code>std::err</code>（為了避免緩存），並在調用輸出操作符的地方設置斷點。如果你繼續執行被調試的程序，執行很可能會停止而不會輸出任何東西。然後你可以重啓調試器並在調用之後設置一個斷點，現在你應該看到成功地輸出了消息。</p><p>查找地址的一個方法是使用 <code>objdump</code>。如果你打開一個終端並執行 <code>objdump -d &lt;your program&gt;</code>，然後你應該看到你的程序的反彙編代碼。你就可以找到 <code>main</code> 函數並定位到你想設置斷點的 <code>call</code> 指令。例如，我編譯了一個 hello world 程序，反彙編它，然後得到了如下的 <code>main</code> 的反彙編代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0000000000400936 &lt;main&gt;:</span></span>
<span class="line"><span>  400936:	55                   	push   %rbp</span></span>
<span class="line"><span>  400937:	48 89 e5             	mov    %rsp,%rbp</span></span>
<span class="line"><span>  40093a:	be 35 0a 40 00       	mov    $0x400a35,%esi</span></span>
<span class="line"><span>  40093f:	bf 60 10 60 00       	mov    $0x601060,%edi</span></span>
<span class="line"><span>  400944:	e8 d7 fe ff ff       	callq  400820 &lt;_ZStlsISt11char_traitsIcEERSt13basic_ostreamIcT_ES5_PKc@plt&gt;</span></span>
<span class="line"><span>  400949:	b8 00 00 00 00       	mov    $0x0,%eax</span></span>
<span class="line"><span>  40094e:	5d                   	pop    %rbp</span></span>
<span class="line"><span>  40094f:	c3                   	retq</span></span></code></pre></div><p>正如你看到的，要沒有輸出，我們要在 <code>0x400944</code> 設置斷點，要看到輸出，要在 <code>0x400949</code> 設置斷點。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>現在你應該有了一個可以啓動程序、允許在內存地址上設置斷點的調試器。後面我們會添加讀寫內存和寄存器的功能。再次説明，如果你有任何問題請在評論框中告訴我。</p>`,37)),s("p",null,[a[10]||(a[10]=n("你可以在",-1)),p(e,{href:"https://github.com/TartanLlama/minidbg/tree/tut_break"},{default:t(()=>[...a[9]||(a[9]=[n("這裏",-1)])]),_:1}),a[11]||(a[11]=n(" 找到該項目的代碼。",-1))]),a[30]||(a[30]=s("hr",null,null,-1)),s("p",null,[a[13]||(a[13]=n("via: ",-1)),p(e,{href:"http://blog.tartanllama.xyz/c++/2017/03/24/writing-a-linux-debugger-breakpoints/"},{default:t(()=>[...a[12]||(a[12]=[n("http://blog.tartanllama.xyz/c++/2017/03/24/writing-a-linux-debugger-breakpoints/",-1)])]),_:1})]),s("p",null,[a[17]||(a[17]=n("作者：",-1)),p(e,{href:"http://blog.tartanllama.xyz/"},{default:t(()=>[...a[14]||(a[14]=[n("Simon Brand",-1)])]),_:1}),a[18]||(a[18]=n(" 譯者：",-1)),p(e,{href:"https://github.com/ictlyh"},{default:t(()=>[...a[15]||(a[15]=[n("ictlyh",-1)])]),_:1}),a[19]||(a[19]=n(" 校對：",-1)),p(e,{href:"https://github.com/jasminepeng"},{default:t(()=>[...a[16]||(a[16]=[n("jasminepeng",-1)])]),_:1})]),s("p",null,[a[22]||(a[22]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[20]||(a[20]=[n("LCTT",-1)])]),_:1}),a[23]||(a[23]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:t(()=>[...a[21]||(a[21]=[n("Linux中國",-1)])]),_:1}),a[24]||(a[24]=n(" 榮譽推出",-1))])])}const v=i(c,[["render",b]]);export{_ as __pageData,v as default};
